function getReadiness(url){return new Promise((resolve,reject)=>{let bytes=0,body='';const req=httpsGet(new URL('/api/v1/readiness',url),{timeout:8000,rejectUnauthorized:true},res=>{res.on('data',b=>{bytes+=b.length;if(bytes>16384)req.destroy();else body+=b;});res.once('end',()=>{try{if(res.statusCode!==200)fail('SSH_HEALTH_NOT_READY');resolve({status:res.statusCode,body,contentType:res.headers['content-type'],cacheControl:res.headers['cache-control']});}catch(e){reject(e);}});});req.once('timeout',()=>req.destroy());req.once('error',()=>reject(Object.assign(Error('SSH_TLS_OR_HEALTH_FAILED'),{code:'SSH_TLS_OR_HEALTH_FAILED'})));});}
